Given a stack st[], Reverse the stack so that the top element becomes the bottom and the bottom element becomes the top, while preserving the order of the remaining elements accordingly.Note: The input array represents the stack from bottom to top (last element is the top). The output is displayed by printing elements from top to bottom after reversal.Example: Input: st[] = [1, 2, 3, 4]Output: [1, 2, 3, 4]Explanation: Input: st[] = [3, 2, 1]Output: [3, 2, 1]Explanation: Try It YourselfTable of Content[Approach 1] Recursive Approach[Approach 2] Iterative Approach - O(n) Time and O(n) Space[Approach 1] Recursive ApproachThe idea is to use the recursion to reverse the given stack.First, we keep removing elements from the stack until stack becomes empty.Once the stack is empty, we start going back in the recursion. At each step, instead of placing the element back on top, we insert it at the bottom of the stack.To insert an element at the bottom, we recursively pop all elements, push the current element, and then put the popped elements back.This way we will ensuring that the element that was originally at the top moves to the bottom, and gradually the entire stack gets reversed.                                                                   
            C++

    #include <iostream>
#include <stack>
using namespace std;

// function to insert element at the bottom of the stack
void insertAtBottom(stack<int> &st, int x) {

    if (st.empty()) {
        st.push(x);
        return;
    }

    // hold the top element and remove it
    int top = st.top();
    st.pop();

    // recursively call to reach the bottom
    insertAtBottom(st, x);

    st.push(top);
}

// function to reverse the stack
void reverseStack(stack<int> &st) {

    if (st.empty()) return;

    // hold the top element and remove it
    int top = st.top();
    st.pop();

    // reverse the remaining stack
    reverseStack(st);

    // insert the held element at the bottom
    insertAtBottom(st, top);
}

int main() {
    stack<int> st;
    st.push(1);
    st.push(2);
    st.push(3);
    st.push(4);

    reverseStack(st);

    while (!st.empty()) {
        cout << st.top() << " ";
        st.pop();
    }

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

#define MAX 100

struct myStack {
    int arr[MAX];
    int top;
};

// function to insert element at the bottom of the stack
void insertAtBottom(struct myStack* st, int x) {
    if (st->top == -1) {
        st->arr[++st->top] = x;
        return;
    }

    // hold the top element and remove it
    int temp = st->arr[st->top--];

    // recursively call to reach the bottom
    insertAtBottom(st, x);

    st->arr[++st->top] = temp;
}

// function to reverse the stack
void reverseStack(struct myStack* st) {
    if (st->top == -1) return;

    // hold the top element and remove it
    int temp = st->arr[st->top--];

    // reverse the remaining stack
    reverseStack(st);

    // insert the held element at the bottom
    insertAtBottom(st, temp);
}

int main() {
    struct myStack st;
    st.top = -1;

    st.arr[++st.top] = 1;
    st.arr[++st.top] = 2;
    st.arr[++st.top] = 3;
    st.arr[++st.top] = 4;

    reverseStack(&st);

    while (st.top != -1) {
        printf("%d ", st.arr[st.top--]);
    }

    return 0;
}


