            C#

    using System;
using System.Collections.Generic;

class GfG {
    static void reverseStack(ref Stack<int> st) {
        Stack<int> aux = new Stack<int>();

        // move all elements to auxiliary stack
        while (st.Count > 0) {
            aux.Push(st.Peek());
            st.Pop();
        }
        st = aux;
    }

    static void Main() {
        Stack<int> st = new Stack<int>();
        st.Push(1);
        st.Push(2);
        st.Push(3);
        st.Push(4);

        reverseStack(ref st);

        while (st.Count > 0) {
            Console.Write(st.Peek() + " ");
            st.Pop();
        }
    }
}


